// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 amount, uint256 t1, uint256 t2) public {
        vm.assume(amount == 10 ether);
        vm.assume(t1 < 2**254);
        vm.assume(t2 <= t1 + 1);
        vm.deal(address(this), amount * 2);
        vm.warp(t1);
        (bool ok1, ) = address(c).call{value: amount}("");
        vm.assume(ok1);
        vm.warp(t2);
        (bool ok2, ) = address(c).call{value: amount}("");
        assertTrue(!ok2);
    }
}
